/** ScriptClient declarations for the client-backed subset, not the Mojang npm package. */
export interface Vector2 { x: number; y: number; }
export interface Vector3 { x: number; y: number; z: number; }
export interface RawMessage { text?: string; rawtext?: RawMessage[]; }
export interface EntityQueryOptions { name?: string; excludeNames?: string[]; }
export interface EntityEffectOptions { amplifier?: number; showParticles?: boolean; }
export type DynamicProperty = boolean | number | string | Vector3;
export const TicksPerSecond: 20;

export class EffectType {
  private constructor();
  getName(): string;
}
export class EffectTypes {
  private constructor();
  static get(identifier: string): EffectType | undefined;
  static getAll(): EffectType[];
}
export class Effect {
  private constructor();
  readonly typeId: string;
  readonly amplifier: number;
  /** Snapshot duration in ticks. */
  readonly duration: number;
}
export class ItemStack {
  constructor(itemType: string, amount?: number);
  readonly typeId: string;
  readonly amount: number;
}
export class Block {
  private constructor();
  readonly typeId: string;
  readonly location: Vector3;
  readonly dimension: Dimension;
  readonly x: number;
  readonly y: number;
  readonly z: number;
}
export class Dimension {
  private constructor();
  readonly id: string;
  getBlock(location: Vector3): Block | undefined;
  getEntities(): Entity[];
  getPlayers(options?: EntityQueryOptions): Player[];
}
export class Entity {
  protected constructor();
  readonly id: string;
  readonly isValid: boolean;
  readonly typeId: string | undefined;
  readonly location: Vector3 | undefined;
  readonly dimension: Dimension | undefined;
  getRotation(): Vector2 | undefined;
  getDynamicProperty(identifier: string): DynamicProperty | undefined;
  setDynamicProperty(identifier: string, value?: DynamicProperty): void;
  getComponent(id: 'health' | 'minecraft:health'): EntityHealthComponent | undefined;
  getComponent(id: 'inventory' | 'minecraft:inventory'): EntityInventoryComponent | undefined;
  getComponent(id: 'equippable' | 'minecraft:equippable'): EntityEquippableComponent | undefined;
  getComponent(id: 'item' | 'minecraft:item'): EntityItemComponent | undefined;
}
export class Player extends Entity {
  private constructor();
  readonly name: string | undefined;
  sendMessage(message: (RawMessage | string)[] | RawMessage | string): void;
  addEffect(effectType: EffectType | string, duration: number, options?: EntityEffectOptions): Effect | undefined;
  removeEffect(effectType: EffectType | string): boolean;
  getEffect(effectType: EffectType | string): Effect | undefined;
  getEffects(): Effect[];
}
export interface EntityHealthComponent {
  readonly typeId: 'minecraft:health';
  readonly currentValue: number;
}
export interface Container {
  readonly size: number;
  getItem(slot: number): ItemStack | undefined;
}
export interface EntityInventoryComponent {
  readonly typeId: 'minecraft:inventory';
  readonly container: Container;
}
export interface EntityEquippableComponent {
  readonly typeId: 'minecraft:equippable';
  getEquipment(slot: EquipmentSlot): ItemStack | undefined;
}
export enum EquipmentSlot {
  Chest = 'Chest',
  Feet = 'Feet',
  Head = 'Head',
  Legs = 'Legs',
  Mainhand = 'Mainhand',
  Offhand = 'Offhand',
}
export interface EntityItemComponent {
  readonly typeId: 'minecraft:item';
  readonly itemStack: ItemStack;
}
export interface PlayerSpawnAfterEvent {
  readonly initialSpawn: boolean;
  readonly player: Player;
}
type PlayerSpawnCallback = (event: PlayerSpawnAfterEvent) => void;
export interface PlayerSpawnAfterEventSignal {
  subscribe(callback: PlayerSpawnCallback): PlayerSpawnCallback;
  unsubscribe(callback: PlayerSpawnCallback): void;
}
export interface WorldAfterEvents { readonly playerSpawn: PlayerSpawnAfterEventSignal; }
export interface WorldBeforeEvents {}
export interface World {
  readonly afterEvents: WorldAfterEvents;
  readonly beforeEvents: WorldBeforeEvents;
  getAllPlayers(): Player[];
  getPlayers(options?: EntityQueryOptions): Player[];
  getDimension(dimensionId: string): Dimension;
  sendMessage(message: (RawMessage | string)[] | RawMessage | string): void;
  getDynamicProperty(identifier: string): DynamicProperty | undefined;
  setDynamicProperty(identifier: string, value?: DynamicProperty): void;
}
export interface System {
  run(callback: () => void): number;
  runTimeout(callback: () => void, tickDelay?: number): number;
  runInterval(callback: () => void, tickInterval?: number): number;
  clearRun(runId: number): void;
}
export const world: World;
export const system: System;
